import random, subprocess, sys, bisect
from functools import lru_cache
WIDTH=[16,8,4]; LANES=[4,8,16]; U=1<<128

def pages_for(span,b,mode):
    K=span if b==0 else b-1
    return ((32+4*b+K*WIDTH[mode]+63)//64)

def compositions(span,maxb=9):
    for b in range(2,min(maxb,span)+1):
        def rec(rem,k,prefix):
            if k==1:
                yield prefix+[rem]
            else:
                for x in range(1,rem-k+2):
                    yield from rec(rem-x,k-1,prefix+[x])
        yield from rec(span,b,[])

def make_stats(starts,bursts):
    R=len(starts); Q=[[0]*(R+1) for _ in range(R+1)]; T=[[0]*(R+1) for _ in range(R+1)]
    qrun=[0]*R
    for repeat,addrs in bursts:
        touched=[0]*R
        for a in addrs:
            r=bisect.bisect_right(starts,a)-1; qrun[r]+=repeat; touched[r]=1
        pref=[0]
        for x in touched: pref.append(pref[-1]+x)
        for i in range(R):
            for j in range(i+1,R+1):
                if pref[j]-pref[i]: T[i][j]+=repeat
    pref=[0]
    for x in qrun: pref.append(pref[-1]+x)
    for i in range(R):
        for j in range(i+1,R+1): Q[i][j]=pref[j]-pref[i]
    return Q,T

def brute_version(starts,hops,Q,T,cost,C):
    R=len(starts)
    @lru_cache(None)
    def sub(i,j):
        span=j-i; out=[]; qv=Q[i][j]; tv=T[i][j]
        spread=starts[j-1]-starts[i]; legal=[0]
        if spread < 1<<64: legal.append(1)
        if spread < 1<<32: legal.append(2)
        if span<=8:
            for mode in legal:
                P=pages_for(span,0,mode); kw=(span+LANES[mode]-1)//LANES[mode]+cost[2][mode]
                out.append((kw*qv+P*cost[1]*tv,P,0))
                if P<=C: out.append((kw*qv+P*cost[0]*tv,P,P))
        for comp in compositions(span):
            b=len(comp); combos=[(0,0,0)]; pos=i
            for x in comp:
                vv=sub(pos,pos+x)
                combos=[(w1+w2,p1+p2,c1+c2) for (w1,p1,c1) in combos for (w2,p2,c2) in vv if c1+c2<=C]
                pos+=x
            for wsum,psum,csum in combos:
                for mode in legal:
                    P=pages_for(span,b,mode); kw=(b-1+LANES[mode]-1)//LANES[mode]+cost[2][mode]
                    base=wsum+kw*qv
                    out.append((base+P*cost[1]*tv,psum+P,csum))
                    if csum+P<=C: out.append((base+P*cost[0]*tv,psum+P,csum+P))
        return tuple(out)
    by={}
    for w,p,c in sub(0,R):
        if c not in by or (w,p)<by[c]: by[c]=(w,p)
    return by

def run_plan(c):
    lines=['PLAN 1']
    hit,miss,dec=c['cost']
    lines.append(' '.join(map(str,[c['cache'],hit,miss,dec[0],dec[1],dec[2],len(c['versions']),len(c['bursts'])])))
    for st,hp in c['versions']:
        lines.append(str(len(st)))
        lines += [f'{x:032x} {-1 if h is None else h}' for x,h in zip(st,hp)]
    for ver,rep,addrs in c['bursts']:
        row=f'{ver} {rep} {len(addrs)}'
        if addrs: row+=' '+' '.join(f'{a:032x}' for a in addrs)
        lines.append(row)
    p=subprocess.run(['tmp/engine_test'],input=('\n'.join(lines)+'\n').encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode: raise RuntimeError(p.stderr.decode())
    out=p.stdout.decode().splitlines(); at=0
    for st,hp in c['versions']: at+=1
    for ver,rep,addrs in c['bursts']:
        A=int(out[at]); at+=1+A
    return tuple(map(int,out[at].split()))

