    versions=[]; bursts=[]
    for v in range(V):
        R=random.randint(1,4)
        starts=[0]
        for _ in range(R-1): starts.append(starts[-1]+random.randint(1,random.choice([10,100,1<<40])))
        hops=[None if random.random()<.15 else random.randint(0,20) for _ in range(R)]
        versions.append((starts,hops))
        for _ in range(random.randint(0,2)):
            rep=random.randint(1,5); addrs=[]
